import { Component, computed, inject } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { toSignal } from '@angular/core/rxjs-interop';
import { HrmButton } from 'hrm-ui';
import { TablerIconComponent, IconArrowLeft } from '@tabler/icons-angular';
import { SgEmployeeDetail } from './employee-detail';
import { findEmployee } from './_data';

/** Trang full-page 1 bản ghi — đích của mode "Toàn trang" / "Tab mới" của hrm-detail-peek.
 *  Đọc ?id=... → hiển thị chi tiết rộng. Route độc lập nên chia sẻ link / mở tab mới được. */
@Component({
  selector: 'sg-doc-record',
  imports: [HrmButton, TablerIconComponent, SgEmployeeDetail],
  template: `
    <div class="rec">
      <div class="rec-bar">
        <hrm-button variant="text" size="sm" (click)="back()">
          <tabler-icon [icon]="icBack" [size]="17" /> Danh sách
        </hrm-button>
        <span class="rec-crumb">Nhân sự / Chi tiết</span>
      </div>

      @if (emp(); as e) {
        <div class="rec-card">
          <sg-employee-detail [emp]="e" [full]="true" />
        </div>
      } @else {
        <div class="rec-empty">Không tìm thấy bản ghi. <a (click)="back()">Về danh sách</a></div>
      }
    </div>
  `,
  styles: [`
    :host { display: block; }
    .rec { max-width: 920px; margin: 0 auto; padding: 8px 4px; }
    .rec-bar { display: flex; align-items: center; gap: 12px; margin-bottom: 16px; }
    .rec-crumb { font-size: var(--fs-13); color: var(--text-soft); }
    .rec-card { padding: 24px; background: var(--bg-surface); border: 1px solid var(--border-sub); border-radius: var(--radius-xl); }
    .rec-empty { padding: 40px; text-align: center; color: var(--text-sub); }
    .rec-empty a { color: var(--primary-base); cursor: pointer; }
  `],
})
export class SgDocRecord {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly params = toSignal(this.route.queryParams, { initialValue: {} as Record<string, string> });

  protected readonly emp = computed(() => findEmployee(this.params()['id'] ?? null));
  protected readonly icBack = IconArrowLeft;

  protected back(): void { this.router.navigateByUrl('/styleguide/hrm/template/list-screen'); }
}
